def forward(groups):
    if groups[1] == '<':
        return {'stored': [0], 'layout': [len(groups[0])]}  # <1 sec means less than 1 second
    if groups[2] is not None:  # It's in the <1 sec format
        return {'stored': [0], 'layout': [len(groups[4])]}
    minutes = int(groups[2])
    seconds = int(groups[3])
    return {'stored': [minutes * 60 + seconds], 'layout': [len(groups[1])]}  # In seconds

def inverse(record):
    seconds = int(record['stored'][0])
    layout = record.get('layout', [])
    sp1_len = layout[0]
    if seconds == 0:
        return '<1' + (' ' * sp1_len) + 'sec'
    minutes = seconds // 60
    seconds %= 60
    return str(minutes).zfill(2) + ':' + str(seconds).zfill(2)
